<template><section class="page-hero"><div class="wrap"><span class="eyebrow light">GESCHÜTZTER BEREICH</span><h1>Gemeinde-<em>Administration</em></h1><p>Verwalten Sie die Bilder unserer Online-Galerie.</p></div></section><section class="wrap section admin-wrap"><div v-if="!firebaseConfigured" class="info-panel"><h3>Firebase noch nicht verbunden</h3><p>Lege eine .env-Datei anhand der .env.example an und trage deine Firebase-Projektdaten ein. Danach kannst du dich hier anmelden.</p></div><div v-else class="admin-card"><template v-if="!user"><h2>Admin-Anmeldung</h2><p class="muted">Nur autorisierte Gemeindeadministratoren haben Zugriff.</p><form @submit.prevent="login"><label>E-Mail-Adresse<input v-model.trim="email" type="email" required autocomplete="username"></label><label>Passwort<input v-model="password" type="password" required autocomplete="current-password"></label><button class="btn btn-dark" :disabled="busy">{{busy?'Bitte warten …':'Anmelden →'}}</button></form></template><template v-else><div class="admin-head"><div><span class="eyebrow">ANGEMELDET</span><h2>Galerie verwalten</h2><p class="muted">{{user.email}}</p></div><button class="btn btn-outline" @click="logout">Abmelden</button></div><div class="upload-panel"><label>Bildtitel<input v-model.trim="title" maxlength="120" placeholder="z. B. Gemeindefest"></label><label class="file-picker">Bilder auswählen<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="chooseFiles"></label><p class="muted">JPEG, PNG oder WebP · max. 8 MB pro Bild. Funktioniert auch auf dem Smartphone.</p><button class="btn btn-dark" :disabled="!files.length || busy" @click="upload">{{busy?'Wird verarbeitet …':` ${files.length} Bild(er) hochladen →`}}</button></div><p v-if="status" class="form-status" role="status">{{status}}</p><div class="admin-gallery"><article v-for="item in images" :key="item.id"><img :src="item.url" :alt="item.title"><div><b>{{item.title||'Ohne Titel'}}</b><button class="delete-btn" @click="remove(item)">Löschen</button></div></article></div></template><p v-if="error" class="form-status error">{{error}}</p></div></section></template>
<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import { onAuthStateChanged, signInWithEmailAndPassword, signOut } from 'firebase/auth'
import { addDoc, collection, deleteDoc, doc, getDocs, orderBy, query, serverTimestamp } from 'firebase/firestore'
import { deleteObject, getDownloadURL, ref as storageRef, uploadBytes } from 'firebase/storage'
import { auth, db, storage, firebaseConfigured } from '../firebase'
const user=ref(null),email=ref(''),password=ref(''),title=ref(''),files=ref([]),images=ref([]),busy=ref(false),status=ref(''),error=ref('')
let unsubscribe=()=>{}
onMounted(()=>{if(firebaseConfigured)unsubscribe=onAuthStateChanged(auth,async u=>{user.value=u;if(u)await loadImages()})})
onUnmounted(()=>unsubscribe())
function chooseFiles(e){files.value=Array.from(e.target.files||[]);status.value='';error.value=''}
async function login(){busy.value=true;error.value='';try{await signInWithEmailAndPassword(auth,email.value,password.value)}catch(e){error.value='Anmeldung fehlgeschlagen. Bitte Zugangsdaten prüfen.'}finally{busy.value=false}}
async function logout(){await signOut(auth);images.value=[]}
async function loadImages(){try{const q=query(collection(db,'gallery'),orderBy('createdAt','desc'));images.value=(await getDocs(q)).docs.map(d=>({id:d.id,...d.data()}))}catch(e){error.value='Galerie konnte nicht geladen werden. Bitte Firestore-Regeln prüfen.'}}
async function upload(){if(!files.value.length)return;busy.value=true;status.value='';error.value='';try{for(const file of files.value){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Bitte nur JPEG-, PNG- oder WebP-Dateien bis 8 MB auswählen.');const path=`gallery/${user.value.uid}/${Date.now()}-${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const r=storageRef(storage,path);await uploadBytes(r,file,{contentType:file.type});const url=await getDownloadURL(r);await addDoc(collection(db,'gallery'),{title:title.value||file.name,url,storagePath:path,createdAt:serverTimestamp(),createdBy:user.value.uid})}status.value='Bilder erfolgreich hochgeladen.';files.value=[];title.value='';await loadImages()}catch(e){error.value=e.message||'Upload fehlgeschlagen. Prüfe deine Firebase-Regeln.'}finally{busy.value=false}}
async function remove(item){if(!confirm(`„${item.title||'Dieses Bild'}“ wirklich löschen?`))return;busy.value=true;try{await deleteDoc(doc(db,'gallery',item.id));if(item.storagePath)await deleteObject(storageRef(storage,item.storagePath));images.value=images.value.filter(i=>i.id!==item.id);status.value='Bild gelöscht.'}catch(e){error.value='Löschen fehlgeschlagen. Bitte Firebase-Regeln prüfen.'}finally{busy.value=false}}
</script>
